package specgen

import (
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"sort"
	"strings"
)

// Generate writes <name>_resource_gen.go for every resource in configPath and
// resources_gen.go listing the generated wrappers, and removes generated files
// for resources no longer configured. apiPath is the client package the
// mapping is checked against (apiv3).
func Generate(specPath, configPath, outDir, apiPath string) error {
	doc, err := Load(specPath)
	if err != nil {
		return err
	}
	cfg, err := LoadConfig(configPath)
	if err != nil {
		return err
	}

	names := make([]string, 0, len(cfg.Resources))
	for name := range cfg.Resources {
		names = append(names, name)
	}
	sort.Strings(names)

	written := map[string]bool{}
	categories := map[string]string{} // resource name -> docs category
	outputs := map[string][]byte{}    // written only after the rename guard passes
	var wrappers []string
	var merged []Resource // every resource, for its example and import files
	variants := map[string]map[string]string{}
	scopes := map[string][]string{} // full type name -> API scopes, for the provider page
	var api *API
	for _, name := range names {
		rc := cfg.Resources[name]
		rc.Entry, rc.Provider = name, cfg.Provider
		resources, err := MergeAll(doc, name, rc)
		if err != nil {
			return err
		}
		for _, res := range resources {
			merged = append(merged, res)
			for _, w := range res.Warnings {
				fmt.Fprintln(os.Stderr, "specgen: warning:", w)
			}
			var m *Mapping
			if rc.API.Model != "" {
				if api == nil {
					if apiPath == "" {
						return fmt.Errorf("resource %s: needs the client package's import path (-api)", name)
					}
					if api, err = LoadAPI(outDir, apiPath); err != nil {
						return err
					}
				}
				if m, err = Map(api, res, rc); err != nil {
					return err
				}
				if m.Wrapper {
					wrappers = append(wrappers, res.Name)
				}
			}
			if len(res.Scopes) > 0 {
				scopes[cfg.Provider+"_"+res.Name] = res.Scopes
			}
			if res.Variant != nil {
				if variants[name] == nil {
					variants[name] = map[string]string{}
				}
				variants[name][res.Variant.Const] = cfg.Provider + "_" + res.Name
			}
			src, err := Render(res, m)
			if err != nil {
				return err
			}
			file := filepath.Join(outDir, res.Name+"_resource_gen.go")
			outputs[file] = src
			written[file] = true
			if rc.DocsCategory != "" {
				categories[res.Name] = rc.DocsCategory
			}
		}
	}

	// A committed generated resource can't disappear unless it's retired
	// (phase 4b spec, 3.6). Check before writing anything, so a refused run
	// leaves the tree unchanged.
	existing, err := filepath.Glob(filepath.Join(outDir, "*_resource_gen.go"))
	if err != nil {
		return err
	}
	var retired []string
	for _, file := range existing {
		if written[file] {
			continue
		}
		name := strings.TrimSuffix(filepath.Base(file), "_resource_gen.go")
		if !slices.Contains(cfg.Retired, name) {
			return fmt.Errorf("generation would remove resource %s (%s); if that's intended, list %s under retired in %s",
				name, filepath.Base(file), name, configPath)
		}
		retired = append(retired, file)
	}

	if err := docsTemplates(cfg, configPath, categories); err != nil {
		return err
	}
	if err := exampleFiles(cfg, configPath, merged); err != nil {
		return err
	}
	for file, src := range outputs {
		if err := os.WriteFile(file, src, 0o644); err != nil {
			return err
		}
	}
	// Always written, even empty, so the provider's call to it compiles.
	registry, err := RenderRegistry(wrappers, variants, scopes)
	if err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(outDir, "resources_gen.go"), registry, 0o644); err != nil {
		return err
	}
	for _, file := range retired {
		if err := os.Remove(file); err != nil {
			return fmt.Errorf("removing retired %s: %w", file, err)
		}
	}
	return nil
}

// docsTemplateMarker starts every docs template specgen writes; a template
// without it is hand-written and left alone.
const docsTemplateMarker = "{{- /* Code generated by specgen. DO NOT EDIT. */ -}}\n"

// docsTemplates writes a tfplugindocs template for each resource with a docs
// category, so its registry page sits in that sidebar group. A hand-written
// template is kept, but must name the same category.
func docsTemplates(cfg Config, configPath string, categories map[string]string) error {
	if len(categories) == 0 {
		return nil
	}
	if cfg.DocsTemplates == "" {
		return fmt.Errorf("%s: docs_category needs docs_templates, the templates directory", configPath)
	}
	dir := filepath.Join(filepath.Dir(configPath), cfg.DocsTemplates, "resources")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	names := keys(categories)
	sort.Strings(names)
	for _, name := range names {
		category := categories[name]
		path := filepath.Join(dir, name+".md.tmpl")
		existing, err := os.ReadFile(path)
		if err == nil && !strings.HasPrefix(string(existing), docsTemplateMarker) {
			if !strings.Contains(string(existing), fmt.Sprintf("subcategory: %q", category)) {
				return fmt.Errorf("resource %s: the hand-written %s must set subcategory: %q, as docs_category says", name, path, category)
			}
			continue
		}
		if err := os.WriteFile(path, []byte(docsTemplateMarker+fmt.Sprintf(docsTemplate, category)), 0o644); err != nil {
			return err
		}
	}
	return nil
}

// docsTemplate is tfplugindocs v0.25's default resource layout, copied
// verbatim (examples and import included), with a subcategory.
const docsTemplate = `---
page_title: "{{.Name}} {{.Type}} - {{.ProviderName}}"
subcategory: %q
description: |-
{{ .Description | plainmarkdown | trimspace | prefixlines "  " }}
---

# {{.Name}} ({{.Type}})

{{ .Description | trimspace }}

{{ if .HasExamples -}}
## Example Usage

{{- range .ExampleFiles }}

{{ tffile . }}
{{- end }}
{{- end }}

{{ .SchemaMarkdown | trimspace }}
{{- if or .HasImport .HasImportIDConfig .HasImportIdentityConfig }}

## Import

Import is supported using the following syntax:
{{- end }}
{{- if .HasImportIdentityConfig }}

In Terraform v1.12.0 and later, the [` + "`" + `import` + "`" + ` block](https://developer.hashicorp.com/terraform/language/import) can be used with the ` + "`" + `identity` + "`" + ` attribute, for example:

{{tffile .ImportIdentityConfigFile }}

{{ .IdentitySchemaMarkdown | trimspace }}
{{- end }}
{{- if .HasImportIDConfig }}

In Terraform v1.5.0 and later, the [` + "`" + `import` + "`" + ` block](https://developer.hashicorp.com/terraform/language/import) can be used with the ` + "`" + `id` + "`" + ` attribute, for example:

{{tffile .ImportIDConfigFile }}
{{- end }}
{{- if .HasImport }}

The [` + "`" + `terraform import` + "`" + ` command](https://developer.hashicorp.com/terraform/cli/commands/import) can be used, for example:

{{codefile "shell" .ImportFile }}
{{- end }}
`
